// Block (composition) — a responsive grid of connectable service cards.
// Card and Switch own look/behavior; Grid and Stack own arrangement.
import type { Ref } from "react";
import { Card } from "../components/Card";
import { Grid } from "../layouts/Grid";
import type { Responsive } from "../layouts/responsive";
import { Stack } from "../layouts/Stack";
import { Switch } from "../components/Switch";
import { SkeletonList } from "./SkeletonList";
import "./IntegrationsList.css";

export interface IntegrationsListProps {
  integrations: {
    id: string;
    name: string;
    description?: string;
    connected?: boolean;
  }[];
  onToggle?: (id: string, connected: boolean) => void;
  columns?: Responsive<number>;
  /** Renders skeleton placeholders while integrations are loading. */
  isLoading?: boolean;
  /** Message shown when there are no integrations. */
  emptyLabel?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function IntegrationsList({
  integrations,
  onToggle,
  columns = { small: 1, medium: 2 },
  isLoading,
  emptyLabel = "No integrations available",
  className,
  ref,
}: IntegrationsListProps) {
  if (isLoading) {
    return <SkeletonList rows={4} className={className} />;
  }
  if (integrations.length === 0) {
    return (
      <p role="status" className={`sd-integrationslist__empty sd-type-caption-medium${className ? ` ${className}` : ""}`}>
        {emptyLabel}
      </p>
    );
  }
  return (
    <Grid
      as="section"
      ref={ref}
      aria-label="Integrations"
      columns={columns}
      gap="medium"
      className={className ? `sd-integrationslist ${className}` : "sd-integrationslist"}
    >
      {integrations.map((integration) => (
        <Card key={integration.id} className="sd-integrationslist__card">
          {/* On the Card's surface, so the name and description take the inset (rule 8); the Switch
              stays on the box line at the end, so only the text is indented. */}
          <Stack direction="row" justify="between" align="center" gap="small" className="sd-integrationslist__row">
            <Stack gap="2x-small" className="sd-integrationslist__details">
              <>
                <h3 className="sd-integrationslist__name sd-type-title-medium">
                  {integration.name}
                </h3>
              </>
              {integration.description && (
                <>
                  <p className="sd-integrationslist__description sd-type-caption-medium">
                    {integration.description}
                  </p>
                </>
              )}
            </Stack>
            <Switch
              aria-label={`${integration.connected ? "Disconnect" : "Connect"} ${integration.name}`}
              isSelected={Boolean(integration.connected)}
              onChange={(connected) => onToggle?.(integration.id, connected)}
            />
          </Stack>
        </Card>
      ))}
    </Grid>
  );
}

/* IntegrationsList.css — .sd-integrationslist (Block)
   Arrangement only: the grid fills its region and card copy can shrink beside its switch. */
.sd-integrationslist {
  width: 100%;
}

.sd-integrationslist__card,
.sd-integrationslist__details {
  min-width: 0;
}

.sd-integrationslist__name,
.sd-integrationslist__description {
  margin: 0;
}

.sd-integrationslist__description {
  color: var(--sd-color-text-muted);
}

/* empty state — layout only (muted color inherits default; blocks own no color) */
.sd-integrationslist__empty {
  padding: var(--sd-space-large);
  text-align: center;
}
